#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <inttypes.h>

static uint64_t mul_mod(uint64_t a, uint64_t b, uint64_t mod) {
    __uint128_t t = ( __uint128_t ) a * b;
    return (uint64_t)(t % mod);
}
static uint64_t pow_mod(uint64_t a, uint64_t e, uint64_t mod) {
    uint64_t res = 1;
    while (e) {
        if (e & 1) res = mul_mod(res, a, mod);
        a = mul_mod(a, a, mod);
        e >>= 1;
    }
    return res;
}
static int is_prime_uint64(uint64_t n) {
    if (n < 2) return 0;
    if (n % 2 == 0) return n == 2;
    if (n % 3 == 0) return n == 3;
    if (n % 5 == 0) return n == 5;
    if (n % 7 == 0) return n == 7;
    if (n % 11 == 0) return n == 11;
    if (n % 13 == 0) return n == 13;
    uint64_t d = n - 1;
    unsigned s = 0;
    while ((d & 1) == 0) { d >>= 1; ++s; }
    const uint64_t bases[] = {2,3,5,7,11,13};
    for (size_t i = 0; i < sizeof(bases)/sizeof(bases[0]); ++i) {
        uint64_t a = bases[i];
        if (a % n == 0) continue;
        uint64_t x = pow_mod(a, d, n);
        if (x == 1 || x == n-1) continue;
        int composite = 1;
        for (unsigned r = 1; r < s; ++r) {
            x = mul_mod(x, x, n);
            if (x == n-1) { composite = 0; break; }
        }
        if (composite) return 0;
    }
    return 1;
}
int main(int argc, char *argv[]) {
    const char *msg;
    if (argc < 2) { puts("NO_INPUT"); return 0; }
    char *endptr = NULL;
    long long ll = strtoll(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') { puts("BAD_INPUT"); return 0; }
    const uint64_t MAX_VAL = 0xBFA17DC6ULL;
    if ((uint64_t)ll > MAX_VAL) { puts("OUT_OF_RANGE"); return 0; }
    uint64_t n = (uint64_t)ll;
    if (is_prime_uint64(n)) msg = "PRIME"; else msg = "NOT_PRIME";
    puts(msg);
    return 0;
}
